INSERT INTO sdpt_data_trnf.udp_brnz.dq_config_rule_registry
  (rule_id, rule_version, rule_name, target_table, target_column, cde_id, rule_type, rule_expr, scope_filter, fail_threshold_pct, severity, business_domain, owner_group, source_layer, status, effective_from, created_by, created_at, promoted_by, promoted_at, note)
VALUES
  ('CTCT_EML_FMT', 1, 'Contact email is well formed (composite)', 'sdpt_data_trnf.udp_brnz.dq_mock_ctct_c', 'EML_ID', NULL, 'format', 'NOT (EML_ID RLIKE \'^[^@\\\\s.]+(\\\\.[^@\\\\s.]+)*@[^@\\\\s.]+(\\\\.[^@\\\\s.]+)+$\')', 'EML_ID IS NOT NULL AND trim(EML_ID) <> \'\'', 0.0, 'P1_block', 'Customer', 'dq-stewards-customer', 'L2', 'active', TIMESTAMP '2026-03-06 03:00:00', 'm.okonkwo@example.com', TIMESTAMP '2026-03-06 03:00:00', 'j.tanaka@example.com', TIMESTAMP '2026-03-06 03:00:00', 'The platform-standard rule. Overlaps the five specific rules below by design.'),
  ('CTCT_EML_NO_AT', 1, 'Contact email contains an @', 'sdpt_data_trnf.udp_brnz.dq_mock_ctct_c', 'EML_ID', NULL, 'format', 'EML_ID NOT LIKE \'%@%\'', 'EML_ID IS NOT NULL AND trim(EML_ID) <> \'\'', 0.0, 'P1_block', 'Customer', 'dq-stewards-customer', 'L2', 'active', TIMESTAMP '2026-03-06 03:00:00', 'm.okonkwo@example.com', TIMESTAMP '2026-03-06 03:00:00', 'j.tanaka@example.com', TIMESTAMP '2026-03-06 03:00:00', 'Half of these have a space where the @ should be -- the signature of a concatenation bug, not user error.'),
  ('CTCT_EML_WHITESPACE', 1, 'Contact email contains no whitespace', 'sdpt_data_trnf.udp_brnz.dq_mock_ctct_c', 'EML_ID', NULL, 'format', 'EML_ID RLIKE \'\\\\s\'', 'EML_ID IS NOT NULL AND trim(EML_ID) <> \'\'', 0.0, 'P2_alert', 'Customer', 'dq-stewards-customer', 'L2', 'active', TIMESTAMP '2026-03-06 03:00:00', 'm.okonkwo@example.com', TIMESTAMP '2026-03-06 03:00:00', 'j.tanaka@example.com', TIMESTAMP '2026-03-06 03:00:00', ''),
  ('CTCT_EML_DOMAIN_TLD', 1, 'Contact email domain has a top-level domain', 'sdpt_data_trnf.udp_brnz.dq_mock_ctct_c', 'EML_ID', NULL, 'format', 'EML_ID LIKE \'%@%\' AND split_part(EML_ID, \'@\', -1) NOT LIKE \'%.%\'', 'EML_ID IS NOT NULL AND trim(EML_ID) <> \'\'', 0.0, 'P2_alert', 'Customer', 'dq-stewards-customer', 'L2', 'active', TIMESTAMP '2026-03-06 03:00:00', 'm.okonkwo@example.com', TIMESTAMP '2026-03-06 03:00:00', 'j.tanaka@example.com', TIMESTAMP '2026-03-06 03:00:00', ''),
  ('CTCT_EML_DOUBLE_DOT', 1, 'Contact email has no consecutive dots', 'sdpt_data_trnf.udp_brnz.dq_mock_ctct_c', 'EML_ID', NULL, 'format', 'EML_ID LIKE \'%..%\'', 'EML_ID IS NOT NULL AND trim(EML_ID) <> \'\'', 0.0, 'P3_monitor', 'Customer', 'dq-stewards-customer', 'L2', 'active', TIMESTAMP '2026-03-06 03:00:00', 'm.okonkwo@example.com', TIMESTAMP '2026-03-06 03:00:00', 'j.tanaka@example.com', TIMESTAMP '2026-03-06 03:00:00', ''),
  ('CTCT_EML_TRAILING_DOT', 1, 'Contact email does not end in a dot', 'sdpt_data_trnf.udp_brnz.dq_mock_ctct_c', 'EML_ID', NULL, 'format', 'EML_ID LIKE \'%.\'', 'EML_ID IS NOT NULL AND trim(EML_ID) <> \'\'', 0.0, 'P3_monitor', 'Customer', 'dq-stewards-customer', 'L2', 'active', TIMESTAMP '2026-03-06 03:00:00', 'm.okonkwo@example.com', TIMESTAMP '2026-03-06 03:00:00', 'j.tanaka@example.com', TIMESTAMP '2026-03-06 03:00:00', ''),
  ('CTCT_EML_NOT_NULL', 1, 'Contact email is present', 'sdpt_data_trnf.udp_brnz.dq_mock_ctct_c', 'EML_ID', NULL, 'not_null', 'EML_ID IS NULL OR trim(EML_ID) = \'\'', NULL, 0.0, 'P2_alert', 'Customer', 'dq-stewards-customer', 'L2', 'active', TIMESTAMP '2026-03-06 03:00:00', 'm.okonkwo@example.com', TIMESTAMP '2026-03-06 03:00:00', 'j.tanaka@example.com', TIMESTAMP '2026-03-06 03:00:00', ''),
  ('CTCT_EML_STTS_NOT_NULL', 1, 'Contact email status code is present', 'sdpt_data_trnf.udp_brnz.dq_mock_ctct_c', 'EML_STTS_CD', NULL, 'not_null', 'EML_STTS_CD IS NULL OR trim(EML_STTS_CD) = \'\'', NULL, 0.0, 'P3_monitor', 'Customer', 'dq-stewards-customer', 'L2', 'active', TIMESTAMP '2026-03-06 03:00:00', 'm.okonkwo@example.com', TIMESTAMP '2026-03-06 03:00:00', 'j.tanaka@example.com', TIMESTAMP '2026-03-06 03:00:00', ''),
  ('CTCT_EML_STTS_CONSISTENT', 1, 'Email marked INVALID is actually malformed', 'sdpt_data_trnf.udp_brnz.dq_mock_ctct_c', 'EML_STTS_CD', NULL, 'consistency', 'EML_STTS_CD = \'INVALID\' AND EML_ID RLIKE \'^[^@\\\\s.]+(\\\\.[^@\\\\s.]+)*@[^@\\\\s.]+(\\\\.[^@\\\\s.]+)+$\'', 'EML_ID IS NOT NULL AND trim(EML_ID) <> \'\'', 0.0, 'P2_alert', 'Customer', 'dq-stewards-customer', 'L2', 'active', TIMESTAMP '2026-03-06 03:00:00', 'm.okonkwo@example.com', TIMESTAMP '2026-03-06 03:00:00', 'j.tanaka@example.com', TIMESTAMP '2026-03-06 03:00:00', 'Passes on this snapshot: the upstream INVALID flag agrees with all 240 defects exactly.'),
