  ('CTCT_MOBL_FMT', 1, 'Contact mobile matches 04########', 'sdpt_data_trnf.udp_brnz.dq_mock_ctct_c', 'MOBL_NO', NULL, 'format', 'MOBL_NO NOT RLIKE \'^04[0-9]{8}$\'', 'MOBL_NO IS NOT NULL AND trim(MOBL_NO) <> \'\'', 0.0, 'P3_monitor', 'Customer', 'dq-stewards-customer', 'L2', 'active', TIMESTAMP '2026-03-06 03:00:00', 'm.okonkwo@example.com', TIMESTAMP '2026-03-06 03:00:00', 'j.tanaka@example.com', TIMESTAMP '2026-03-06 03:00:00', ''),
  ('CTCT_PHN_FMT', 1, 'Contact landline matches 0#########', 'sdpt_data_trnf.udp_brnz.dq_mock_ctct_c', 'PHN_NO', NULL, 'format', 'PHN_NO NOT RLIKE \'^0[0-9]{9}$\'', 'PHN_NO IS NOT NULL AND trim(PHN_NO) <> \'\'', 0.0, 'P3_monitor', 'Customer', 'dq-stewards-customer', 'L2', 'active', TIMESTAMP '2026-03-06 03:00:00', 'm.okonkwo@example.com', TIMESTAMP '2026-03-06 03:00:00', 'j.tanaka@example.com', TIMESTAMP '2026-03-06 03:00:00', ''),
  ('CTCT_KEY_UNIQUE', 1, 'Contact key is unique', 'sdpt_data_trnf.udp_brnz.dq_mock_ctct_c', 'CTCT_KEY', NULL, 'uniqueness', 'count(*) OVER (PARTITION BY CTCT_KEY) > 1', NULL, 0.0, 'P1_block', 'Customer', 'dq-stewards-customer', 'L2', 'active', TIMESTAMP '2026-03-06 03:00:00', 'm.okonkwo@example.com', TIMESTAMP '2026-03-06 03:00:00', 'j.tanaka@example.com', TIMESTAMP '2026-03-06 03:00:00', ''),
  ('CTCT_BRTH_PARSEABLE', 1, 'Date of birth parses as a real ISO date', 'sdpt_data_trnf.udp_brnz.dq_mock_ctct_c', 'BRTH_TS', NULL, 'format', 'try_to_timestamp(BRTH_TS, \'yyyy-MM-dd HH:mm:ss\') IS NULL', 'BRTH_TS IS NOT NULL AND trim(BRTH_TS) <> \'\'', 0.0, 'P1_block', 'Customer', 'dq-stewards-customer', 'L2', 'active', TIMESTAMP '2026-03-06 03:00:00', 'm.okonkwo@example.com', TIMESTAMP '2026-03-06 03:00:00', 'j.tanaka@example.com', TIMESTAMP '2026-03-06 03:00:00', 'All 14 are the same literal \'31-02-1988\' -- one bad default, not fourteen bad records.'),
  ('CTCT_BRTH_PLAUSIBLE', 1, 'Date of birth is plausible (age 18-105)', 'sdpt_data_trnf.udp_brnz.dq_mock_ctct_c', 'BRTH_TS', NULL, 'format', 'year(BRTH_TS) < 1920 OR year(BRTH_TS) > 2008', 'try_to_timestamp(BRTH_TS, \'yyyy-MM-dd HH:mm:ss\') IS NOT NULL', 0.0, 'P2_alert', 'Customer', 'dq-stewards-customer', 'L2', 'active', TIMESTAMP '2026-03-06 03:00:00', 'm.okonkwo@example.com', TIMESTAMP '2026-03-06 03:00:00', 'j.tanaka@example.com', TIMESTAMP '2026-03-06 03:00:00', ''),
  ('CTCT_IDNT_DOC_NOT_NULL', 1, 'Identity document number present when type is set', 'sdpt_data_trnf.udp_brnz.dq_mock_ctct_c', 'IDNT_DOC_1_NO', NULL, 'consistency', 'IDNT_DOC_1_NO IS NULL OR trim(IDNT_DOC_1_NO) = \'\'', 'IDNT_TYPE_1_CD IS NOT NULL AND trim(IDNT_TYPE_1_CD) <> \'\'', 0.0, 'P1_block', 'Customer', 'dq-stewards-customer', 'L2', 'active', TIMESTAMP '2026-03-06 03:00:00', 'm.okonkwo@example.com', TIMESTAMP '2026-03-06 03:00:00', 'j.tanaka@example.com', TIMESTAMP '2026-03-06 03:00:00', ''),
  ('CTCT_SPCL_CARE_VARIANCE', 1, 'Special-care status carries more than one value', 'sdpt_data_trnf.udp_brnz.dq_mock_ctct_c', 'SPCL_CARE_STTS', NULL, 'variance', '(SELECT count(DISTINCT SPCL_CARE_STTS) FROM {table}) <= 1', NULL, 0.0, 'P2_alert', 'Customer', 'dq-stewards-customer', 'L2', 'active', TIMESTAMP '2026-03-06 03:00:00', 'm.okonkwo@example.com', TIMESTAMP '2026-03-06 03:00:00', 'j.tanaka@example.com', TIMESTAMP '2026-03-06 03:00:00', 'A vulnerable-customer flag that is constant is almost certainly not being populated.'),
  ('CTCT_PREF_LANG_VARIANCE', 1, 'Preferred language carries more than one value', 'sdpt_data_trnf.udp_brnz.dq_mock_ctct_c', 'PREF_LANG_NM', NULL, 'variance', '(SELECT count(DISTINCT PREF_LANG_NM) FROM {table}) <= 1', NULL, 0.0, 'P3_monitor', 'Customer', 'dq-stewards-customer', 'L2', 'shadow', TIMESTAMP '2026-03-06 03:00:00', 'm.okonkwo@example.com', TIMESTAMP '2026-03-06 03:00:00', NULL, NULL, 'Shadow: measured every run but never raises a cohort. Exercises the shadow->active promotion path.'),
  ('SUBS_MSISDN_SENTINEL', 1, 'Mobile service number is not a placeholder', 'sdpt_data_trnf.udp_brnz.dq_mock_subs_c', 'PRIM_RSRC_VALU_TXT', NULL, 'sentinel', 'lower(trim(PRIM_RSRC_VALU_TXT)) IN (\'service-number-unknown\',\'unknown\',\'n/a\',\'na\',\'none\',\'null\',\'\')', 'PRIM_RSRC_TYPE_KEY = 1', 0.0, 'P1_block', 'Customer', 'dq-stewards-customer', 'L2', 'active', TIMESTAMP '2026-03-06 03:00:00', 'm.okonkwo@example.com', TIMESTAMP '2026-03-06 03:00:00', 'j.tanaka@example.com', TIMESTAMP '2026-03-06 03:00:00', 'A live mobile service with no number is a provisioning gap, not a formatting nit.'),
  ('SUBS_MSISDN_FMT', 1, 'Mobile service number matches 04########', 'sdpt_data_trnf.udp_brnz.dq_mock_subs_c', 'PRIM_RSRC_VALU_TXT', NULL, 'format', 'PRIM_RSRC_VALU_TXT NOT RLIKE \'^04[0-9]{8}$\'', NULL, 0.0, 'P2_alert', 'Customer', 'dq-stewards-customer', 'L2', 'active', TIMESTAMP '2026-03-06 03:00:00', 'm.okonkwo@example.com', TIMESTAMP '2026-03-06 03:00:00', 'm.okonkwo@example.com', TIMESTAMP '2026-03-06 03:00:00', 'v1 had no scope_filter and reported 212 violations, 200 of which were Fixed Broadband service IDs in a different and correct format. Scoping to PRIM_RSRC_TYPE_KEY = 1 took it to 12 real ones. This is the fix COH-B is recommending for the two rules that still have the same defect.'),
  ('SUBS_MSISDN_FMT', 2, 'Mobile service number matches 04########', 'sdpt_data_trnf.udp_brnz.dq_mock_subs_c', 'PRIM_RSRC_VALU_TXT', NULL, 'format', 'PRIM_RSRC_VALU_TXT NOT RLIKE \'^04[0-9]{8}$\'', 'PRIM_RSRC_TYPE_KEY = 1', 0.0, 'P2_alert', 'Customer', 'dq-stewards-customer', 'L2', 'active', TIMESTAMP '2026-07-19 03:00:00', 'm.okonkwo@example.com', TIMESTAMP '2026-07-19 03:00:00', 'j.tanaka@example.com', TIMESTAMP '2026-07-19 03:00:00', ''),
  ('SUBS_MSISDN_UNIQUE', 1, 'Mobile service number is not reused across subscriptions', 'sdpt_data_trnf.udp_brnz.dq_mock_subs_c', 'PRIM_RSRC_VALU_TXT', NULL, 'uniqueness', 'count(*) OVER (PARTITION BY PRIM_RSRC_VALU_TXT) > 1', 'PRIM_RSRC_TYPE_KEY = 1 AND lower(trim(PRIM_RSRC_VALU_TXT)) <> \'service-number-unknown\'', 0.0, 'P1_block', 'Customer', 'dq-stewards-customer', 'L2', 'active', TIMESTAMP '2026-03-06 03:00:00', 'm.okonkwo@example.com', TIMESTAMP '2026-03-06 03:00:00', 'j.tanaka@example.com', TIMESTAMP '2026-03-06 03:00:00', ''),
  ('SUBS_IMEI_NOT_NULL', 1, 'Handset IMEI is present', 'sdpt_data_trnf.udp_brnz.dq_mock_subs_c', 'IMEI_ID', NULL, 'not_null', 'IMEI_ID IS NULL OR trim(IMEI_ID) = \'\'', NULL, 0.0, 'P3_monitor', 'Customer', 'dq-stewards-customer', 'L2', 'active', TIMESTAMP '2026-03-06 03:00:00', 'm.okonkwo@example.com', TIMESTAMP '2026-03-06 03:00:00', 'j.tanaka@example.com', TIMESTAMP '2026-03-06 03:00:00', 'MISSING SCOPE FILTER, DELIBERATELY. All 200 violations are Fixed Broadband. See COH-B.'),
  ('SUBS_SIM_NOT_NULL', 1, 'SIM serial is present for SIM-bearing products', 'sdpt_data_trnf.udp_brnz.dq_mock_subs_c', 'SIM_SERL_ID', NULL, 'not_null', 'SIM_SERL_ID IS NULL OR trim(SIM_SERL_ID) = \'\'', 'PROD_TYPE_KEY <> 0', 0.0, 'P2_alert', 'Customer', 'dq-stewards-customer', 'L2', 'active', TIMESTAMP '2026-03-06 03:00:00', 'm.okonkwo@example.com', TIMESTAMP '2026-03-06 03:00:00', 'j.tanaka@example.com', TIMESTAMP '2026-03-06 03:00:00', 'The correctly-scoped twin of SUBS_IMEI_NOT_NULL. Same data, zero violations.'),
  ('SUBS_NTWK_NOT_NULL', 1, 'Network technology is populated', 'sdpt_data_trnf.udp_brnz.dq_mock_subs_c', 'NTWK_TECH_NM', NULL, 'not_null', 'NTWK_TECH_NM IS NULL OR trim(NTWK_TECH_NM) = \'\'', NULL, 0.0, 'P2_alert', 'Customer', 'dq-stewards-customer', 'L2', 'active', TIMESTAMP '2026-03-06 03:00:00', 'm.okonkwo@example.com', TIMESTAMP '2026-03-06 03:00:00', 'j.tanaka@example.com', TIMESTAMP '2026-03-06 03:00:00', 'Genuinely spread across all three product lines, so scope is not the explanation here.'),
  ('SUBS_PRIM_ACCT_NOT_ZERO', 1, 'Primary billing account is set', 'sdpt_data_trnf.udp_brnz.dq_mock_subs_c', 'PRIM_ACCT_KEY', NULL, 'sentinel', 'PRIM_ACCT_KEY = 0', NULL, 0.0, 'P2_alert', 'Customer', 'dq-stewards-customer', 'L2', 'active', TIMESTAMP '2026-03-06 03:00:00', 'm.okonkwo@example.com', TIMESTAMP '2026-03-06 03:00:00', 'j.tanaka@example.com', TIMESTAMP '2026-03-06 03:00:00', 'MISSING SCOPE FILTER, DELIBERATELY. All 500 violations are prepaid. See COH-B.'),
  ('SUBS_BILL_OFFR_NOT_ZERO', 1, 'Main billing offer is set for postpaid', 'sdpt_data_trnf.udp_brnz.dq_mock_subs_c', 'MAIN_BILL_OFFR_KEY', NULL, 'sentinel', 'MAIN_BILL_OFFR_KEY = 0', 'BILL_SUBS_TYPE_CD = \'POSTPAID\'', 0.0, 'P1_block', 'Billing', 'dq-stewards-billing', 'L2', 'active', TIMESTAMP '2026-03-06 03:00:00', 'm.okonkwo@example.com', TIMESTAMP '2026-03-06 03:00:00', 'j.tanaka@example.com', TIMESTAMP '2026-03-06 03:00:00', ''),
  ('SUBS_ACTV_TS_CONSISTENT', 1, 'Original and initial activation timestamps agree', 'sdpt_data_trnf.udp_brnz.dq_mock_subs_c', 'ORIG_ACTV_TS', NULL, 'consistency', 'ORIG_ACTV_TS <> INIT_ACTV_TS', NULL, 0.0, 'P3_monitor', 'Customer', 'dq-stewards-customer', 'L2', 'active', TIMESTAMP '2026-03-06 03:00:00', 'm.okonkwo@example.com', TIMESTAMP '2026-03-06 03:00:00', 'j.tanaka@example.com', TIMESTAMP '2026-03-06 03:00:00', ''),
  ('SUBS_STTS_RSN_REQUIRED', 1, 'Non-active subscription carries a status reason', 'sdpt_data_trnf.udp_brnz.dq_mock_subs_c', 'SUBS_STTS_RSN_KEY', NULL, 'consistency', 'SUBS_STTS_RSN_KEY = 0 OR SUBS_STTS_RSN_KEY IS NULL', 'SUBS_STTS_KEY <> 1', 0.0, 'P2_alert', 'Customer', 'dq-stewards-customer', 'L2', 'active', TIMESTAMP '2026-03-06 03:00:00', 'm.okonkwo@example.com', TIMESTAMP '2026-03-06 03:00:00', 'j.tanaka@example.com', TIMESTAMP '2026-03-06 03:00:00', ''),
  ('SUBS_KEY_UNIQUE', 1, 'Subscription key is unique', 'sdpt_data_trnf.udp_brnz.dq_mock_subs_c', 'SUBS_KEY', NULL, 'uniqueness', 'count(*) OVER (PARTITION BY SUBS_KEY) > 1', NULL, 0.0, 'P1_block', 'Customer', 'dq-stewards-customer', 'L2', 'active', TIMESTAMP '2026-03-06 03:00:00', 'm.okonkwo@example.com', TIMESTAMP '2026-03-06 03:00:00', 'j.tanaka@example.com', TIMESTAMP '2026-03-06 03:00:00', ''),
  ('SUBS_CLSE_TS_CONSISTENT', 1, 'Record close timestamp agrees with cancelled status', 'sdpt_data_trnf.udp_brnz.dq_mock_subs_c', 'ECF_CLSE_TS', NULL, 'consistency', '(ECF_CLSE_TS IS NOT NULL) <> (SUBS_STTS_KEY = 2)', NULL, 0.0, 'P2_alert', 'Customer', 'dq-stewards-customer', 'L2', 'active', TIMESTAMP '2026-03-06 03:00:00', 'm.okonkwo@example.com', TIMESTAMP '2026-03-06 03:00:00', 'j.tanaka@example.com', TIMESTAMP '2026-03-06 03:00:00', ''),
  ('SUBS_BNFT_TXT_NOT_NULL', 1, 'Benefit text is populated', 'sdpt_data_trnf.udp_brnz.dq_mock_subs_c', 'BNFT_TXT', NULL, 'not_null', 'BNFT_TXT IS NULL OR trim(BNFT_TXT) = \'\'', NULL, 90.0, 'P3_monitor', 'Customer', 'dq-stewards-customer', 'L2', 'shadow', TIMESTAMP '2026-03-06 03:00:00', 'm.okonkwo@example.com', TIMESTAMP '2026-03-06 03:00:00', NULL, NULL, 'Shadow at a 90% threshold. 75% blank looks alarming but is probably an optional field. Left in shadow precisely because nobody has confirmed which -- promoting it on a hunch is how a queue fills with noise.'),
  ('XREF_SUBS_CTCT_ORPHAN', 1, 'Every subscription resolves to a contact', 'sdpt_data_trnf.udp_brnz.dq_mock_subs_c', NULL, NULL, 'referential', 'c.CTCT_KEY IS NULL', NULL, 0.0, 'P1_block', 'Customer', 'dq-stewards-customer', 'L2', 'active', TIMESTAMP '2026-03-06 03:00:00', 'm.okonkwo@example.com', TIMESTAMP '2026-03-06 03:00:00', 'j.tanaka@example.com', TIMESTAMP '2026-03-06 03:00:00', ''),
