INSERT INTO sdpt_data_trnf.udp_brnz.dq_config_playbook
  (playbook_id, rule_id, rule_type, approach_name, approach_type, description, typical_owner, status, prior_use_count, recurrence_count, recurrence_rate, last_used_ts, created_by, created_at)
VALUES
  ('PB_UPSTREAM_SOURCE_RELEASE', NULL, 'format', 'Raise upstream ticket against the source release', 'upstream_ticket', 'Where a defect starts on a date that matches a source-system release, the correction belongs in that system. Raise a ticket against the release, attach the cohort\'s before/after counts, and hold the cohort open until the source ships. Do NOT correct the warehouse copy: while the source keeps emitting bad rows the warehouse would disagree with the system of record, which the spec rules out explicitly.', 'CRM Platform Team', 'active', 3, 0, 0.0, TIMESTAMP '2026-08-31 10:00:00', 'm.okonkwo@example.com', TIMESTAMP '2026-02-14 03:00:00'),
  ('PB_RULE_SCOPE_AMENDMENT', NULL, 'not_null', 'Amend the rule scope, not the data', 'accept_and_document', 'Where every violating row shares a product line or account type that legitimately does not carry the column, the rule is wrong, not the data. Reject the cohort with the reason recorded, then author a new rule version carrying the scope_filter and promote it through the registry. The rejection is the audit record that the rows were examined and found correct.', 'dq-stewards-customer', 'active', 0, 0, 0.0, NULL, 'm.okonkwo@example.com', TIMESTAMP '2026-02-14 03:00:00'),
  ('PB_PROVISIONING_BACKFILL', 'SUBS_MSISDN_SENTINEL', NULL, 'Route to provisioning for reissue', 'source_correction', 'A live service carrying a placeholder resource value cannot be corrected in the warehouse -- the real number does not exist anywhere yet. Route to provisioning to issue and publish the resource; the warehouse picks it up on the next load.', 'Provisioning Team', 'active', 2, 0, 0.0, TIMESTAMP '2026-08-25 10:00:00', 'm.okonkwo@example.com', TIMESTAMP '2026-02-14 03:00:00'),
  ('PB_PIPELINE_RERUN', NULL, 'consistency', 'Re-run the load for the affected window', 'pipeline_rerun', 'Where the source is correct and the warehouse copy is not, re-run the load for the affected partition window. Re-derives rather than amends, which is why this is the only class the spec flags as a candidate for assisted execution later.', 'Data Platform', 'active', 3, 0, 0.0, TIMESTAMP '2026-08-11 09:00:00', 'm.okonkwo@example.com', TIMESTAMP '2026-02-14 03:00:00'),
  ('PB_MANDATORY_FIELD_CAMPAIGN', NULL, 'not_null', 'Field-completion campaign with the owning channel', 'upstream_ticket', 'For genuinely absent attributes with no upstream defect, the fix is collection, not correction. Agree a completion target with the owning channel and track it as a deferred cohort with a review-by date rather than leaving it open.', 'Customer Operations', 'active', 0, 0, 0.0, NULL, 'm.okonkwo@example.com', TIMESTAMP '2026-02-14 03:00:00'),
  ('PB_ACCEPT_KNOWN_LIMITATION', NULL, 'variance', 'Accept and document a known source limitation', 'accept_and_document', 'Where a column is constant because the source system never populates it, and there is no plan to change that, record the acceptance with a reason so the cohort stops recurring silently. Revisit if the source system changes.', 'dq-stewards-customer', 'active', 0, 0, 0.0, NULL, 'm.okonkwo@example.com', TIMESTAMP '2026-02-14 03:00:00');
INSERT INTO sdpt_data_trnf.udp_brnz.dq_config_cde_registry
  (cde_id, cde_version, cde_name, business_term, data_class, definition, expected_signature, criticality, pii, regulatory_basis, bindings, business_domain, owner_group, status, effective_from, registered_by, registered_at, note)
VALUES
  ('CDE_CUST_EMAIL', 1, 'Customer email address', 'Customer contact email', 'email_address', 'The email address the business uses to reach a customer for servicing, billing and consent-bearing communications. Not a marketing preference and not an account login.', '^[^@\\s.]+(\\.[^@\\s.]+)*@[^@\\s.]+(\\.[^@\\s.]+)+$', 'high', TRUE, 'Privacy Act 1988 (Cth) APP 10 — quality of personal information', array(named_struct('target_table', 'sdpt_data_trnf.udp_brnz.dq_mock_ctct_c', 'target_column', 'EML_ID', 'populated_when', NULL, 'expected_scope_filter', NULL, 'binding_status', 'bound', 'discovered_by', 'manual', 'confidence', 1.0)), 'Customer', 'dq-stewards-customer', 'registered', TIMESTAMP '2026-02-14 03:00:00', 'r.delacruz@example.com', TIMESTAMP '2026-02-14 03:00:00', 'The best-covered element in the register: seven active rules, one composite and six specific. Registered as high rather than critical because an undeliverable address delays a communication; it does not misidentify a person.'),
  ('CDE_CUST_MSISDN', 1, 'Mobile service number (MSISDN)', 'Service number', 'msisdn', 'The mobile number a service is reachable on. Identifies the service to the network, to the customer and to every downstream system, which is why it is the one element here tiered critical on availability rather than on privacy.', '^04\\d{8}$', 'critical', TRUE, 'Telecommunications Consumer Protections Code C628 — service identification', array(named_struct('target_table', 'sdpt_data_trnf.udp_brnz.dq_mock_subs_c', 'target_column', 'PRIM_RSRC_VALU_TXT', 'populated_when', 'the primary resource on the service is a mobile number', 'expected_scope_filter', 'PRIM_RSRC_TYPE_KEY = 1', 'binding_status', 'bound', 'discovered_by', 'manual', 'confidence', 1.0)), 'Customer', 'dq-stewards-customer', 'registered', TIMESTAMP '2026-02-14 03:00:00', 'r.delacruz@example.com', TIMESTAMP '2026-02-14 03:00:00', 'The column name says nothing — PRIM_RSRC_VALU_TXT holds whatever resource type the service uses. Only the data identifies it, which is why a register built from column names alone would have missed it entirely.'),
  ('CDE_CUST_DOB', 1, 'Customer date of birth', 'Date of birth', 'date_of_birth', 'The customer\'s date of birth as evidenced at onboarding. Used for identity verification, for age-gating, and for the credit assessment that a contract service depends on.', '^\\d{4}-\\d{2}-\\d{2} \\d{2}:\\d{2}:\\d{2}$', 'high', TRUE, 'AML/CTF Act 2006 s.32 — KYC identity evidence', array(named_struct('target_table', 'sdpt_data_trnf.udp_brnz.dq_mock_ctct_c', 'target_column', 'BRTH_TS', 'populated_when', NULL, 'expected_scope_filter', NULL, 'binding_status', 'bound', 'discovered_by', 'manual', 'confidence', 1.0)), 'Customer', 'dq-stewards-customer', 'registered', TIMESTAMP '2026-02-14 03:00:00', 'r.delacruz@example.com', TIMESTAMP '2026-02-14 03:00:00', 'The element where profiling earns its place on its own. The fourteen values written DD-MM-YYYY carry a different masked signature from the other 986, so they show up in top_signatures as a minority shape before any rule asserts anything about the column.'),
  ('CDE_CUST_NAME', 1, 'Customer name', 'Customer legal name', 'person_name', 'The name of the person the account is held by, as given on identity evidence. Three columns realise it: the full legal name and its parsed given and family components.', NULL, 'high', TRUE, 'AML/CTF Act 2006 s.32 — KYC identity evidence', array(named_struct('target_table', 'sdpt_data_trnf.udp_brnz.dq_mock_ctct_c', 'target_column', 'LEGL_NM', 'populated_when', NULL, 'expected_scope_filter', NULL, 'binding_status', 'bound', 'discovered_by', 'manual', 'confidence', 1.0), named_struct('target_table', 'sdpt_data_trnf.udp_brnz.dq_mock_ctct_c', 'target_column', 'FRST_NM', 'populated_when', NULL, 'expected_scope_filter', NULL, 'binding_status', 'bound', 'discovered_by', 'manual', 'confidence', 1.0), named_struct('target_table', 'sdpt_data_trnf.udp_brnz.dq_mock_ctct_c', 'target_column', 'LAST_NM', 'populated_when', NULL, 'expected_scope_filter', NULL, 'binding_status', 'bound', 'discovered_by', 'manual', 'confidence', 1.0)), 'Customer', 'dq-stewards-customer', 'registered', TIMESTAMP '2026-02-14 03:00:00', 'r.delacruz@example.com', TIMESTAMP '2026-02-14 03:00:00', 'High criticality, and the only rule that touches it is a cross-table agreement check with no target_column — so a coverage view joining on columns alone would report zero rules on a KYC element and be wrong about why. That is what rule_registry.cde_id is for. Even counting it, all three bindings are watched by one consistency rule and nothing else: no format rule, no presence rule, no uniqueness. This is a real gap, left in place because reporting it is the point.'),
  ('CDE_CUST_IDENT_DOC', 1, 'Identity document number', 'Identity evidence document number', 'national_id', 'The number of the document presented as identity evidence at onboarding — passport, driver licence or equivalent, as typed in IDNT_TYPE_1_CD. The single most sensitive element in the register.', '^\\d{7}$', 'critical', TRUE, 'AML/CTF Act 2006 s.32 — KYC identity evidence; Privacy Act 1988 (Cth) APP 11', array(named_struct('target_table', 'sdpt_data_trnf.udp_brnz.dq_mock_ctct_c', 'target_column', 'IDNT_DOC_1_NO', 'populated_when', 'an identity document type has been recorded for the contact', 'expected_scope_filter', 'IDNT_TYPE_1_CD IS NOT NULL AND trim(IDNT_TYPE_1_CD) <> \'\'', 'binding_status', 'bound', 'discovered_by', 'manual', 'confidence', 1.0)), 'Customer', 'dq-stewards-customer', 'registered', TIMESTAMP '2026-02-14 03:00:00', 'r.delacruz@example.com', TIMESTAMP '2026-02-14 03:00:00', 'Critical, PII, KYC-bearing — and watched by exactly one rule, which only checks that the field is not empty. Nothing verifies the number is well formed for its document type, and nothing checks it is not shared between two people. The coverage panel classifies this \'unvalidated\' and it is the strongest argument in the register for having built the register.'),
  ('CDE_CUST_MOBILE', 1, 'Customer contact mobile number', 'Contact mobile', 'phone_number', 'The mobile number used to reach the person, as distinct from the MSISDN a service runs on. The two are frequently the same number and are not the same element — one is a contact detail, the other is a network resource.', '^04\\d{8}$', 'high', TRUE, 'Privacy Act 1988 (Cth) APP 10 — quality of personal information', array(named_struct('target_table', 'sdpt_data_trnf.udp_brnz.dq_mock_ctct_c', 'target_column', 'MOBL_NO', 'populated_when', NULL, 'expected_scope_filter', NULL, 'binding_status', 'bound', 'discovered_by', 'manual', 'confidence', 1.0)), 'Customer', 'dq-stewards-customer', 'registered', TIMESTAMP '2026-02-14 03:00:00', 'r.delacruz@example.com', TIMESTAMP '2026-02-14 03:00:00', ''),
  ('CDE_CUST_LANDLINE', 1, 'Customer contact landline number', 'Contact landline', 'phone_number', 'The fixed-line number recorded against the contact, where one is held.', '^0\\d{9}$', 'medium', TRUE, 'Privacy Act 1988 (Cth) APP 10 — quality of personal information', array(named_struct('target_table', 'sdpt_data_trnf.udp_brnz.dq_mock_ctct_c', 'target_column', 'PHN_NO', 'populated_when', NULL, 'expected_scope_filter', NULL, 'binding_status', 'bound', 'discovered_by', 'manual', 'confidence', 1.0)), 'Customer', 'dq-stewards-customer', 'registered', TIMESTAMP '2026-02-14 03:00:00', 'r.delacruz@example.com', TIMESTAMP '2026-02-14 03:00:00', 'Medium: a stale landline degrades reach, it does not misidentify or misbill.'),
  ('CDE_SIM_SERIAL', 1, 'SIM serial number', 'SIM serial', 'device_id', 'The serial of the SIM provisioned to a service. Identifies the SIM to the network and is the key to a replacement or port.', '^\\d{7}$', 'medium', FALSE, NULL, array(named_struct('target_table', 'sdpt_data_trnf.udp_brnz.dq_mock_subs_c', 'target_column', 'SIM_SERL_ID', 'populated_when', 'services that carry a SIM — everything except fixed broadband', 'expected_scope_filter', 'PROD_TYPE_KEY <> 0', 'binding_status', 'bound', 'discovered_by', 'manual', 'confidence', 1.0)), 'Subscription', 'dq-stewards-subscription', 'registered', TIMESTAMP '2026-02-14 03:00:00', 'r.delacruz@example.com', TIMESTAMP '2026-02-14 03:00:00', 'The correctly-scoped counterpart to IMEI below. Its rule carries the same scope_filter the binding declares, so the coverage view finds no mismatch — which is what makes the mismatch it does find on IMEI meaningful rather than an artefact of how the check is written.'),
  ('CDE_DEVICE_IMEI', 1, 'Device IMEI', 'Handset IMEI', 'device_id', 'The identity of the handset attached to a service. Only exists where the service involves a handset at all.', '^\\d{7}$', 'medium', FALSE, NULL, array(named_struct('target_table', 'sdpt_data_trnf.udp_brnz.dq_mock_subs_c', 'target_column', 'IMEI_ID', 'populated_when', 'handset services only — fixed broadband has no handset and never will', 'expected_scope_filter', 'PROD_TYPE_KEY <> 0', 'binding_status', 'bound', 'discovered_by', 'manual', 'confidence', 1.0)), 'Subscription', 'dq-stewards-subscription', 'registered', TIMESTAMP '2026-02-14 03:00:00', 'r.delacruz@example.com', TIMESTAMP '2026-02-14 03:00:00', 'COH-B, stated as a contradiction rather than as a discovery. The binding says this column is only populated for handset services. SUBS_IMEI_NOT_NULL carries no scope_filter and so measures every row, reporting 200 fixed-broadband services as defects. v_cde_coverage flags the rule by id. The rule is left unscoped on purpose — see CLAUDE.md; the register\'s job here is to show that the data is fine and the rule is not.'),
  ('CDE_BILLING_ACCOUNT', 1, 'Primary billing account', 'Billing account key', 'account_id', 'The billing account a service charges to. Postpaid services have one by definition; prepaid services do not have one at all.', '^\\d{7}$', 'high', FALSE, NULL, array(named_struct('target_table', 'sdpt_data_trnf.udp_brnz.dq_mock_subs_c', 'target_column', 'PRIM_ACCT_KEY', 'populated_when', 'postpaid services only — a prepaid service has no billing account', 'expected_scope_filter', 'BILL_SUBS_TYPE_CD = \'POSTPAID\'', 'binding_status', 'bound', 'discovered_by', 'manual', 'confidence', 1.0)), 'Subscription', 'dq-stewards-subscription', 'registered', TIMESTAMP '2026-02-14 03:00:00', 'r.delacruz@example.com', TIMESTAMP '2026-02-14 03:00:00', 'The second half of COH-B. SUBS_PRIM_ACCT_NOT_ZERO is unscoped and reports every prepaid service as a defect; the binding says prepaid never carries one. Its correctly-scoped twin SUBS_BILL_OFFR_NOT_ZERO checks a different column on the same rows and returns zero.');
